 var itemJson = JSON.parse(vaVars.itemJSON);
 var variablesObj = {};
 var attachmentIds = [];
 for (i = 0; i < itemJson.variables.length; i++) {
 variablesObj[itemJson.variables[i].name] = itemJson.variables[i].value;
 if (itemJson.variables[i].type === 33)
 attachmentIds.push(itemJson.variables[i].value);
 }
 var reqObject = {
 "sysparm_id" : itemJson.sys_id,
 "sysparm_action" : 'execute_producer',
 "variables" : variablesObj,
 "engagement_channel" : 'va'
 }
 var response = new sn_sc.CatItem(itemJson.sys_id).submitProducer(reqObject);
 if (response) {
 vaVars.record_id = response.sys_id;
 vaVars.record_table = response.table;
 // add attachment to record
 var mediaLinksFormAttachment = vaVars.media_links_form_attachment.split(',');
 for (var i in mediaLinksFormAttachment)
 vaSystem.attachToRecord(mediaLinksFormAttachment[i], response.table, response.sys_id);

 // move attachment variable to record
 var gr = new GlideRecord('sys_attachment');
 gr.addQuery('sys_id', 'IN' , attachmentIds);
 gr.query();
 while (gr.next()) {
 gr.setValue('table_name', 'ZZ_YY' + response.table);
 gr.setValue('table_sys_id', response.sys_id);
 gr.update();
 }
 }
})()
","id":"8fb89065d150429487db975b1272593f","name":"Insert the Record","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false},{"type":"InputPrompt","variable_id":"24784fef3a7c40229ea0c0db7b2b38ca","message":{"type":"String","mode":"string","value":"gs.getMessageLang("va:topic:5c32e9b547f4ea10f0631ce4316d43e2:node:f7d41b80c7764dd1b1b9dda3acc23754:field:Message", vaContext.getRequesterLang())"},"nlu_entity_binding":{"type":"NLUEntityBinding","allow_text_input":false,"use_confirmation_prompt":true},"request_feedback":false,"skippable":{"type":"Applicability","mode":"script","value":"false"},"skipreprompt":{"type":"Applicability","mode":"script","value":"false"},"id":"f7d41b80c7764dd1b1b9dda3acc23754","name":"Order Item","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false,"formatType":"Text","validationScript":"","description":""},{"type":"Decision","name":"Decision","branches":[{"type":"Branch","label":"Don't Order","expression":{"type":"Applicability","mode":"query","value":"order_item="},"id":"2bf4645cf1ec479ab21f59b7d227fe7c","name":"Don't Order","expert_mode":false},{"type":"Branch","label":"Order Now","expression":{"type":"Applicability","mode":"query","value":"order_item=true"},"id":"f789016ed4024b988875e8d2749faa25","name":"Order Now","expert_mode":false}],"id":"015876b57058499b89fb0f0b0e0ed843","goal_id":"primary","expert_mode":false},{"type":"ScriptedAction","script":"(function execute() {
 var itemJson = JSON.parse(vaVars.itemJSON);
 var cartname = "vacart_" + gs.generateGUID();
 var cartObj = new sn_sc.CartJS(cartname);
 cartObj.setRequestedFor(vaVars.request_for);
 cartObj.setEngagementChannel('va');

 var variablesObj = {};
 var attachmentIds = [];
 for (i = 0; i < itemJson.variables.length; i++) {
 variablesObj[itemJson.variables[i].name] = itemJson.variables[i].value;
 if (itemJson.variables[i].type === 33)
 attachmentIds.push(itemJson.variables[i].value);
 }


 var reqObj = {
 "sysparm_id" : itemJson.sys_id,
 "variables" : variablesObj
 };
 cartObj.addToCart(reqObj);
 var requestResponse = cartObj.checkoutCart(true);
 var requestGr = new GlideRecord('sc_request');
 if (requestGr.get(requestResponse.request_id)) {
 var reqItemGr = new GlideRecord('sc_req_item');
 reqItemGr.addQuery("request", requestResponse.request_id);
 reqItemGr.query();
 if (reqItemGr.next()) {
 vaVars.record_id = reqItemGr.getUniqueValue();
 vaVars.record_table = 'sc_req_item';
 // add attachment to record
 var mediaLinksFormAttachment = vaVars.media_links_form_attachment.split(',');
 for (var i in mediaLinksFormAttachment)
 vaSystem.attachToRecord(mediaLinksFormAttachment[i], vaVars.record_table, vaVars.record_id);

 }
 // move attachment variable to record
 var gr = new GlideRecord('sys_attachment');
 gr.addQuery('sys_id', 'IN' , attachmentIds);
 gr.query();
 while (gr.next()) {
 gr.setValue('table_name', 'ZZ_YY' + vaVars.record_table);
 gr.setValue('table_sys_id', vaVars.record_id);
 gr.update();
 }
 }
})()","id":"907092bb1dbc48f7a4ae115e87ceb201","name":"Checkout Cart","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false},{"type":"Decision","name":"Decision","branches":[{"type":"Branch","label":"Question Requested For","expression":{"type":"Applicability","mode":"script","value":"(function() { return (function execute() {
