})()})()"},"id":"a124efc8a1824857ae17f57534061576","name":"Reference Question","expert_mode":false}],"id":"6e2ebbdb139b4b2bbd694be7637422e5","goal_id":"primary","expert_mode":false},{"type":"InputPrompt","variable_id":"c31318903433407fafbc5e2e9ce7ba65","message":{"type":"String","mode":"script","value":"(function execute() {
 var quesJson = JSON.parse(vaVars.itemJSON).variables[vaVars.qIndex];
 var response = quesJson.label;
 var json = new JSON();
 var infoKeys = json.getKeys(quesJson.field_info_messages);
 var warnKeys = json.getKeys(quesJson.field_warn_messages);
 var errKeys = json.getKeys(quesJson.field_error_messages);

 for (var j = infoKeys.length - 1; j >= 0; j--) {
 response += "\n" + gs.getMessageLang("Info", vaContext.getRequesterLang()) + ": " + quesJson.field_info_messages[infoKeys[j]];
 }
 for (j = warnKeys.length - 1; j >= 0; j--) {
 response += "\n" + gs.getMessageLang("Warning", vaContext.getRequesterLang()) + ": " + quesJson.field_warn_messages[warnKeys[j]];
 }
 for (j = errKeys.length - 1; j >= 0; j--) {
 response += "\n" + gs.getMessageLang("Error", vaContext.getRequesterLang()) + ": " + quesJson.field_error_messages[errKeys[j]];
 }
 return response;
})()"},"nlu_entity_binding":{"type":"NLUEntityBinding","allow_text_input":false,"use_confirmation_prompt":true},"request_feedback":false,"skippable":{"type":"Applicability","mode":"script","value":"(function() { return (function execute() {
 return !JSON.parse(vaVars.itemJSON).variables[vaVars.qIndex].mandatory;
})()
})()"},"skipreprompt":{"type":"Applicability","mode":"script","value":"false"},"id":"9e6e235f722149a58b678031d642cc77","name":"Question Date","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false,"formatType":"Text","validationScript":"","description":""},{"type":"ScriptedAction","script":"(function execute() {
 var itemJson = JSON.parse(vaVars.itemJSON);
 vaVars.validation_message = "";
 var quesJson = itemJson.variables[vaVars.qIndex];
 var type = quesJson.type;
 var vaFieldValidator = new global.VAFieldValidator();
 // If user doesn't want to proceed with the selected value and skips the question, the variable would be set to ""
 var proceedWithDefaultValue = vaInputs.proceed_with_default.getValue();
 switch (type) {
 case 2:
 case 6:
 case 16:
 var ans = vaInputs.question_text.getValue() || (proceedWithDefaultValue ? quesJson.display_value : "");
 if (ans.trim().length === 0 && itemJson.variables[vaVars.qIndex].mandatory) {
 vaVars.validation_message = gs.getMessageLang('You must answer this question', vaContext.getRequesterLang());
 break;
 }
 if (type === 2) {
 itemJson.variables[vaVars.qIndex].value = ans;
 vaInputs.question_text = "";
 break;
 }
 var q = GlideappQuestion.getQuestion(itemJson.variables[vaVars.qIndex].sys_id);
 var validresponse = q.validateRegex(ans);
 if (validresponse) {
 itemJson.variables[vaVars.qIndex].value = ans;
 vaInputs.question_text = "";
 } else if (!validresponse)
 vaVars.validation_message = q.getValidationMessage();
 break;
 case 7:
 var ans = (proceedWithDefaultValue ? quesJson.value : "");
 if (vaInputs.question_choice.getValue()) {
 switch (vaInputs.question_choice.getValue()) {
 case "yes":
 ans = "true";
 break;
 case "no":
 case "no_data":
 case "":
 ans = "false";
 break;
 default:
 ans = "false";
 break;
 }
 }
 if (itemJson.variables[vaVars.qIndex].mandatory && ans == "false")
 vaVars.validation_message = gs.getMessageLang('It is a mandatory question, you cannot select No as the answer', vaContext.getRequesterLang());
 else
 itemJson.variables[vaVars.qIndex].value = ans;
 vaInputs.question_choice = "";
 break;
 case 9:
 itemJson.variables[vaVars.qIndex].value = vaInputs.question_date.getDisplayValue() || (proceedWithDefaultValue ? quesJson.display_value : "");
 vaInputs.question_date = "";
 break;
 case 10:
 itemJson.variables[vaVars.qIndex].value = vaInputs.question_date_time.getDisplayValue() || (proceedWithDefaultValue ? quesJson.display_value : "");
 vaInputs.question_date_time = "";
 break;
 case 8:
 var ans = (proceedWithDefaultValue ? quesJson.value : "");
 if (vaInputs.question_reference)
 ans = vaInputs.question_reference.getValue();

 itemJson.variables[vaVars.qIndex].value = ans;
 vaInputs.question_reference = "";
 break;
 case 1:
 case 3:
 case 4:
 case 5:
 case 18:
 case 22:
 var ans = (proceedWithDefaultValue ? quesJson.value : "");
 if (vaInputs.question_choice) {
 ans = vaInputs.question_choice.getValue();
 ans = ans == 'no_data' ? '' : ans;
 }
 itemJson.variables[vaVars.qIndex].value = ans;
 vaInputs.question_choice = "";
 break;
 case 26:
 var ans = vaInputs.question_email.getValue() || (proceedWithDefaultValue ? quesJson.value : "");
 if (vaInputs.question_email.getValue() || ans == "" || vaFieldValidator.validateEmailAddress(ans)) {
 itemJson.variables[vaVars.qIndex].value = ans;
 vaInputs.question_email = "";
 } else
 vaVars.validation_message = gs.getMessageLang("This isn't a valid email address", vaContext.getRequesterLang());
 break;
 case 27:
 var ans = vaInputs.question_url.getValue() || (proceedWithDefaultValue ? quesJson.value : "");
 if (vaInputs.question_url.getValue() || ans == "" || vaFieldValidator.validateURL(ans)) {
 itemJson.variables[vaVars.qIndex].value = ans;
 vaInputs.question_url = "";
 } else
 vaVars.validation_message = gs.getMessageLang("This isn't a valid URL", vaContext.getRequesterLang());
 break;
 case 28:
 var ans = vaInputs.question_ip_address.getValue() || (proceedWithDefaultValue ? quesJson.value : "");
 if (vaInputs.question_ip_address.getValue() || ans == "" || vaFieldValidator.validateIPAddress(ans)) {
 itemJson.variables[vaVars.qIndex].value = ans;
 vaInputs.question_ip_address = "";
 } else
 vaVars.validation_message = gs.getMessageLang("This isn't a valid IP Address", vaContext.getRequesterLang());
 break;
 case 31:
 var ans = quesJson.default_value + '';
 if (quesJson.default_value && proceedWithDefaultValue)
 vaVars.request_for = ans;
 else if (vaVars.request_for)
 ans = vaVars.request_for;
 itemJson.variables[vaVars.qIndex].value = ans;
 }
 itemJson.variables[vaVars.qIndex].field_info_messages = {};
 itemJson.variables[vaVars.qIndex].field_warn_messages = {};
 itemJson.variables[vaVars.qIndex].field_error_messages = {};

 if (!vaVars.request_for)
 vaVars.request_for = gs.getUserID() + '';
 var executeDataLookup = false;
 var executeDynamicValue = false;
 if (quesJson.data_lookup_ids && quesJson.data_lookup_ids.length != 0)
 executeDataLookup = true;
 if (itemJson.dynamic_value_variable_config && itemJson.dynamic_value_variable_config[quesJson.sys_id] && itemJson.dynamic_value_variable_config[quesJson.sys_id].length != 0)
 executeDynamicValue = true;
 if (executeDataLookup || executeDynamicValue) {
 var helper = new sn_sc.CatalogConversationHelper();
 vaVars.itemJSON = JSON.stringify(helper.executeVariableChangeHandlers(itemJson, quesJson.sys_id, executeDataLookup, executeDynamicValue));
 } else
 vaVars.itemJSON = JSON.stringify(itemJson);

// resetting the value of proceed with default incase validation fails
 if (vaVars.validation_message.length !== 0)
 vaInputs.proceed_with_default = false;

})()
