 var contextualSearch = new global.VAGlobalContextualSearchUtil();
 var response = contextualSearch.search(
 vaVars.contextualSearchContext, vaInputs.question_text.getValue(), ''
 );
 var success = contextualSearch.processSearchResponse(response);
 if (!success) {
 return;
 } 
 var relevantSearchResults = contextualSearch.processGeneralResults(response, 20, -2, vaSystem);
 vaVars.contextualSearchResultCount = relevantSearchResults.length;
 vaVars.contextualSearchResultJsonString = JSON.stringify(relevantSearchResults);
 vaVars.contextualSearchIndex = 0;
 return;
})()
